// One item per PDF attachment (an email can carry several invoices).
const out = [];
for (const item of $input.all()) {
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if ((bin.mimeType || '').includes('pdf') || (bin.fileName || '').toLowerCase().endsWith('.pdf')) {
      out.push({
        json: {
          messageId: item.json.id,
          subject: item.json.subject,
          from: item.json.from?.emailAddress?.address ?? '',
          receivedAt: item.json.receivedDateTime,
          fileName: bin.fileName,
        },
        binary: { data: bin },
      });
    }
  }
}
return out;  // emails without PDFs simply stop here

const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    is_invoice: { type: 'boolean' },
    supplier_name: { type: 'string' },
    supplier_tax_id: { type: 'string' },
    invoice_number: { type: 'string' },
    invoice_date: { type: 'string', description: 'YYYY-MM-DD or empty' },
    due_date: { type: 'string', description: 'YYYY-MM-DD or empty' },
    currency: { type: 'string' },
    net_amount: { type: ['number', 'null'] },
    vat_amount: { type: ['number', 'null'] },
    total_amount: { type: ['number', 'null'] },
    confidence: { type: 'integer', minimum: 0, maximum: 100 },
  },
  required: ['is_invoice', 'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date', 'due_date',
             'currency', 'net_amount', 'vat_amount', 'total_amount', 'confidence'],
};

return [{ json: {
  ...$json,
  openai_payload: {
    model: $env.OPENAI_MODEL || 'gpt-5.6-luna',
    instructions: 'Extract invoice data from the document text. Copy values exactly as printed; do not calculate or guess. ' + 'Use empty strings or null when a field is not present. Dates as YYYY-MM-DD.',
    input: `File: ${$json.fileName}\nEmail subject: ${$json.subject}\n\n${String($json.text || '').slice(0, 15000)}`,
    text: { format: { type: 'json_schema', name: 'invoice_extraction', strict: true, schema } },
  },
} }];

function parseResponse(res) {
  const message = (res.output || []).find(o => o.type === 'message');
  const part = message?.content?.find(c => c.type === 'output_text' || c.type === 'refusal');
  if (!part || part.type === 'refusal') throw new Error('The model returned no usable answer: ' + JSON.stringify(res).slice(0, 300));
  return JSON.parse(part.text);
}

// Business rules are checked in code, never trusted to the model.
const src = $('Build extraction request').item.json;
const inv = parseResponse($json);
const issues = [];

if (!inv.is_invoice) issues.push('The document does not look like an invoice');
for (const f of ['supplier_name', 'invoice_number', 'invoice_date']) if (!inv[f]) issues.push(`Missing ${f}`);
if (inv.invoice_date && !/^\d{4}-\d{2}-\d{2}$/.test(inv.invoice_date)) issues.push('Invalid invoice date');
if (inv.total_amount == null) issues.push('Missing total');
if (inv.net_amount != null && inv.vat_amount != null && inv.total_amount != null) {
  const diff = Math.abs(inv.net_amount + inv.vat_amount - inv.total_amount);
  if (diff > 0.02) issues.push(`Net + VAT ≠ total (difference ${diff.toFixed(2)})`);
}
if (inv.confidence < 70) issues.push(`Low confidence (${inv.confidence})`);

return [{ json: {
  ...inv,
  ok: issues.length === 0,
  issues: issues.join('; '),
  messageId: src.messageId,
  email_subject: src.subject,
  email_from: src.from,
  file_name: src.fileName,
  processed_at: new Date().toISOString(),
} }];

// Only the columns of the Excel table (column names must match the table headers).
return $input.all().map(({ json: i }) => ({ json: {
  processed_at: i.processed_at, supplier_name: i.supplier_name, supplier_tax_id: i.supplier_tax_id,
  invoice_number: i.invoice_number, invoice_date: i.invoice_date, due_date: i.due_date, currency: i.currency,
  net_amount: i.net_amount, vat_amount: i.vat_amount, total_amount: i.total_amount,
  confidence: i.confidence, file_name: i.file_name, email_from: i.email_from,
} }));

// Move each processed email once, even if it carried several invoice PDFs.
const ids = $('Validate in code').all().filter(i => i.json.ok).map(i => i.json.messageId);
return [...new Set(ids)].map(messageId => ({ json: { messageId } }));

return [{ json: {
  html: `<b>🧾 Invoice needs review</b><br>
<b>File:</b> ${$json.file_name}<br>
<b>From:</b> ${$json.email_from} · <i>${$json.email_subject}</i><br>
<b>Supplier:</b> ${$json.supplier_name || '?'} · <b>Total:</b> ${$json.total_amount ?? '?'} ${$json.currency || ''}<br>
<b>Issues:</b> ${$json.issues}`,
} }];
